// wf.scam.check > "Agent input"
// The system message is the active P8_scam_agent version from the prompt registry, with its variables filled in; the
// user part (the listing between <message> tags) is what the agent receives. No memory: each check is independent.
const s = $('Start').first().json;
const c = $('Context').first().json.ctx;
const k = $('Agent context').first().json;
const p = k.prompt_row || {};
const template = p.template || p.body || '';
const params = p.params || {};
const base = { listing_id: c.listing_id, model: s.model || k.model, num_ctx: k.num_ctx, keep_alive: '10m',
  max_iterations: 6, t0: Date.now(), prompt_version_id: p.version_id || p.id || null, prompt_version: p.version || null };
if (!template) return [{ json: { ...base, ok: false, error_code: 'prompt_missing', prompt_keys: Object.keys(p) } }];
const vars = { message: c.text || '', jurisdiction: c.jurisdiction_code || 'unknown', today: new Date().toISOString().slice(0, 10) };
const fill = (t) => t.replace(/\{\{\s*([a-z_]+)\s*\}\}/gi, (m, n) => (n in vars ? String(vars[n]) : m));
const m = /##\s*system\s*\n([\s\S]*?)\n##\s*user\s*\n([\s\S]*)$/i.exec(template);
if (!m) return [{ json: { ...base, ok: false, error_code: 'prompt_invalid' } }];
return [{ json: { ...base, ok: true, system: fill(m[1].trim()), text: fill(m[2].trim()), num_predict: params.num_predict || 200 } }];

// wf.scam.check > "Agent output"
// The AI Agent node's answer and tool calls: the moderator note (plain text; kept only if every number in it comes from
// the listing or a tool result, agent_check.checkAnswer), the contact_reuse results and the list of tools it chose.
// No answer (model down, iteration limit) -> agent_ok false: the detector and the rules still score the listing.
// A3 Match agent checks (D-084), shared by the agent workflow and the unit tests.
//  - toolCalls(steps): the AI Agent node's intermediate steps as [{tool, input, output}] (output parsed when JSON).
//  - numbersIn(text): every reading of every number written in a text (see readings).
//  - checkAnswer(answer, sources): every number of two digits or more in the answer must appear in one of the
//    sources (the user's message, the tool results). Small numbers (result positions, counts up to 10) pass.
//  - fallbackMask(text): e-mails and long digit runs masked, used only when the Text service did not answer.
//  - plainText(answer): Markdown removed (bold, italics, headings, list markers, links), lines joined (D-085).
//  - shorten(text, max): cut at the last sentence end that fits, else at a word, with an ellipsis (D-085).

function toolCalls(steps) {
  return (Array.isArray(steps) ? steps : []).map((s) => {
    const a = s.action || {};
    let out = s.observation;
    if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { /* keep the text */ } }
    if (Array.isArray(out) && out.length === 1) out = out[0];          // a workflow tool answers with its items
    let input = a.toolInput;
    if (typeof input === 'string') { try { input = JSON.parse(input); } catch (e) { /* keep the text */ } }
    return { tool: a.tool || null, input: input ?? null, output: out ?? null };
  });
}

// Each number written in a text, with its possible readings: "450.000" is 450 (Tunisian dinars, three decimals) or
// 450000 (dot as thousands separator); "1.225.000" is 1225000; "450,5" is 450.5.
function readings(text) {
  const out = [];
  for (const m of String(text || '').matchAll(/\d{1,3}(?:\.\d{3})+(?!\d|,\d)|\d+(?:[.,]\d+)?/g)) {
    const raw = m[0];
    const alts = new Set();
    if (/^\d{1,3}(?:\.\d{3})+$/.test(raw)) alts.add(Number(raw.replace(/\./g, '')));
    const v = Number(raw.replace(',', '.'));
    if (Number.isFinite(v)) alts.add(v);
    out.push([...alts]);
  }
  return out;
}

function numbersIn(text) {
  return readings(text).flat();
}

function checkAnswer(answer, sources) {
  const allowed = new Set();
  for (const src of sources || []) {
    const text = typeof src === 'string' ? src : JSON.stringify(src ?? '');
    for (const n of numbersIn(text)) {
      allowed.add(n);
      allowed.add(Math.round(n));
    }
  }
  const unsupported = [];
  for (const alts of readings(answer)) {
    if (alts.some((n) => Number.isInteger(n) && n <= 10)) continue;
    if (alts.some((n) => allowed.has(n) || allowed.has(Math.round(n)))) continue;
    unsupported.push(alts[alts.length - 1]);
  }
  return { ok: unsupported.length === 0, unsupported };
}

function fallbackMask(text) {
  return String(text || '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '<EMAIL>')
    .replace(/\+?\d[\d .-]{6,}\d/g, (m) => (m.replace(/\D/g, '').length >= 8 ? '<PHONE>' : m));
}

function plainText(answer) {
  const lines = String(answer || '').replace(/\r/g, '').split('\n').map((l) => l
    .replace(/^\s{0,3}#{1,6}\s+/, '')                      // headings
    .replace(/^\s*(?:[-*+\u2022]|\d+[.)])\s+/, '')            // list markers ("1." too: positions are said in words)
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')                // links: keep the text
    .replace(/(\*\*|__)(.+?)\1/g, '$2')                       // bold
    .replace(/(^|[^\w*])[*_]([^*_\n]+)[*_](?=[^\w*]|$)/g, '$1$2') // italics
    .replace(/`([^`]*)`/g, '$1')
    .replace(/[*_]{2,}/g, '')
    .trim()).filter(Boolean);
  return lines.join(' ').replace(/\s{2,}/g, ' ').trim();
}

function shorten(text, max) {
  const t = String(text || '');
  if (!max || Array.from(t).length <= max) return { text: t, cut: false };
  const head = Array.from(t).slice(0, max).join('');
  const ends = [...head.matchAll(/[.!?\u061F\u06D4](?=\s|$)/g)].map((m) => m.index + 1);
  if (ends.length && ends[ends.length - 1] >= max * 0.4) return { text: head.slice(0, ends[ends.length - 1]).trim(), cut: true };
  const sp = head.lastIndexOf(' ');
  return { text: (sp > max * 0.4 ? head.slice(0, sp) : head).trim() + '\u2026', cut: true };
}

if (typeof module !== 'undefined') module.exports = { toolCalls, readings, numbersIn, checkAnswer, fallbackMask, plainText, shorten };

// Scam agent (A4): reading the AI Agent node's final answer and its tool calls.
// The final answer must be one JSON object {signals, prices_in_text, note}; text around it (a sentence, a ```json fence)
// is ignored. Anything else is not trusted: the check then runs on the rules alone.

function scamParseAnswer(raw) {
  const s = String(raw || '');
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  let o;
  try { o = JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
  if (!o || typeof o !== 'object' || !Array.isArray(o.signals)) return null;
  return { signals: o.signals.filter((x) => x && typeof x === 'object').slice(0, 8),
    prices_in_text: Array.isArray(o.prices_in_text) ? o.prices_in_text.filter((x) => x && typeof x === 'object').slice(0, 10) : [],
    note: typeof o.note === 'string' ? o.note.trim().slice(0, 400) : '' };
}

function scamToolOutput(x) {
  if (x == null) return null;
  if (typeof x === 'object') return x;
  try { return JSON.parse(String(x)); } catch (e) { return null; }
}

// contact_reuse results seen by the agent: [{contact, other_listings, other_owners}] (database counts, not model words).
function scamContactReuse(calls) {
  const out = [];
  for (const c of Array.isArray(calls) ? calls : []) {
    if (!c || c.tool !== 'contact_reuse') continue;
    const o = scamToolOutput(c.output);
    if (o && o.contact != null) out.push({ contact: String(o.contact), other_listings: Number(o.other_listings) || 0,
      other_owners: Number(o.other_owners) || 0 });
  }
  return out;
}

if (typeof module !== 'undefined') module.exports = { scamParseAnswer, scamContactReuse };

const a = $('Agent input').first().json;
const latency = Date.now() - (a.t0 || Date.now());
const base = { agent_model: a.model || null, agent_prompt_version_id: a.prompt_version_id || null, agent_latency_ms: latency };
if (!a.ok) return [{ json: { ...base, agent_ok: false, agent_error: a.error_code || 'agent_input', note: null, contact_reuse: [], tool_calls: [] } }];
const r = $input.first().json;
const calls = toolCalls(r.intermediateSteps);
const err = r.error ? String(r.error.message || r.error).slice(0, 300) : null;
let note = typeof r.output === 'string' ? plainText(r.output) : '';
let dropped = null;
if (note) {
  const chk = checkAnswer(note, [a.text, ...calls.map((x) => (typeof x.output === 'string' ? x.output : JSON.stringify(x.output)))]);
  if (chk.ok) note = shorten(note, 300).text; else { dropped = chk.unsupported; note = null; }
}
return [{ json: { ...base, agent_ok: !err && !!note, agent_error: err || (dropped ? 'note_unsupported_numbers' : (note ? null : 'no_answer')),
  note: note || null, contact_reuse: scamContactReuse(calls), tool_calls: calls.map((x) => x.tool) } }];

// wf.scam.check > "Detect input": the wf.llm.call input for P8_scam_detector (the evaluated single-call prompt) on the
// listing's title and description; it gives the quoted text signals and the amounts written.
const s = $('Start').first().json;
const c = $('Context').first().json.ctx;
return [{ json: { prompt: 'P8_scam_detector', version: s.version ?? null, model: s.model || null,
  vars: { message: c.text, jurisdiction: c.jurisdiction_code, today: new Date().toISOString().slice(0, 10) },
  meta: { listing_id: c.listing_id } } }];

// wf.scam.check > "Score"
// Deterministic part: price, profile, price_mismatch and contact reuse signals, the detector's quoted signals (checked
// against the text), score and level from the scam.* settings. The agent's tools and note are kept as evidence for the
// moderator. A model or agent failure does not stop the check: the rules still apply.
// Scam check (A4): deterministic signals and score. The agent only lists text signals with quotes (P8_scam_agent);
// price, profile, price_mismatch, contact reuse, weights and thresholds are computed here from app.scam_context
// (settings scam.*). Evidence of rule signals is data (numbers, codes), never sentences.
const MODEL_TYPES = ['off_platform_payment', 'advance_payment', 'owner_abroad', 'urgency', 'external_contact'];
// Contexts are normalized (no accents, lower case) before these tests.
const RENT_CTX = /\b(rent|loyer|kra|price|prix|real|reel|vrai|actual|monthly|mensuel)\b|per month|par mois/;
const OTHER_CTX = /\b(deposit|caution|fees?|frais|bills?|transfer|virement)\b/;
const RENT_WORD = /\b(rent|loyer|kra)\b/;
const CURRENCY_ALIAS = { 'dt': 'TND', 'tnd': 'TND', 'dinar': 'TND', 'dinars': 'TND',
  '€': 'EUR', 'eur': 'EUR', 'euro': 'EUR', 'euros': 'EUR', '$': 'USD', 'usd': 'USD', '£': 'GBP', 'gbp': 'GBP' };
const CONTACT_REUSED_WEIGHT = 20;   // used until scam.weights has a contact_reused entry

function normText(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function normCurrency(c) {
  if (!c) return null;
  const k = String(c).trim().toLowerCase();
  return CURRENCY_ALIAS[k] || k.toUpperCase();
}

function quoteInText(quote, text) {
  const q = normText(quote);
  return q.length >= 4 && normText(text).includes(q);
}

// Numbers written in the text, with the usual separators: 1200, 1 200, 1.200, 1,200, 1200.50.
function numbersIn(text) {
  const out = new Set();
  for (const m of String(text || '').matchAll(/\d(?:[\d.,]|\s(?=\d{3}\b))*/g)) {
    const s = m[0].replace(/[.,]+$/, '').replace(/\s/g, '');
    for (const c of [s.replace(/[.,]/g, ''), s.replace(/,/g, '.'), s.replace(/\./g, '').replace(',', '.'), s.replace(/,/g, '')]) {
      const n = Number(c);
      if (Number.isFinite(n)) out.add(n);
    }
  }
  return out;
}

// Anti-hallucination for amounts: the model's amount must be written in the listing text.
function amountInText(amount, text) {
  for (const n of numbersIn(text)) if (Math.abs(n - amount) < 0.005) return true;
  return false;
}

// A phone (last 8 digits) or an e-mail is "in the text" only if the listing really contains it.
function contactInText(contact, text) {
  const c = String(contact || '').trim();
  if (c.includes('@')) return c.length >= 6 && normText(text).includes(normText(c));
  const d = c.replace(/\D/g, '');
  return d.length >= 8 && String(text || '').replace(/\D/g, '').includes(d.slice(-8));
}

function monthlyOf(amount, period) {
  return period === 'week' ? (amount * 52) / 12 : amount;
}

// Missing settings must fail loudly: zero weights would silently pass every listing as "low".
function requireSettings(S) {
  const missing = ['scam.weights', 'scam.price_ratio', 'scam.thresholds'].filter((k) => !S[k] || typeof S[k] !== 'object');
  if (missing.length) throw new Error(`scam settings missing: ${missing.join(', ')}`);
}

// Rent against the median of comparable listings (same unit: monthly, minor units).
function priceSignal(ctx, W) {
  const m = ctx.market || {};
  const R = ctx.settings['scam.price_ratio'];
  if (ctx.rent_minor == null || !m.median_monthly_minor || ctx.rent_scope === 'whole_flat') return null;
  const ratio = monthlyOf(Number(ctx.rent_minor), ctx.rent_period) / Number(m.median_monthly_minor);
  let type = null;
  if (ratio <= R.very_low) type = 'price_very_low';
  else if (ratio <= R.low) type = 'price_low';
  else if (ratio >= R.very_high) type = 'price_very_high';
  else if (ratio >= R.high) type = 'price_high';
  if (!type) return null;
  const full = W[type] || 0;
  const weight = m.scope === 'jurisdiction' ? Math.round(full / 2) : full;
  return { type, source: 'rule', weight,
    evidence: { ratio: Math.round(ratio * 100) / 100, median_monthly_minor: m.median_monthly_minor, scope: m.scope, comparables: m.comparables } };
}

// An amount written as a rent in the text that is far from the stored rent (title says 300, text says 900).
// Compared to the closest of stored / stored-as-monthly, so a weekly rent quoted per month is not a mismatch.
// An amount the model gives but that is not in the text is dropped (reason amount_not_in_text).
function mismatchSignal(ctx, pricesInText, W, dropped) {
  if (ctx.rent_minor == null || !Array.isArray(pricesInText)) return null;
  const exp = ctx.currency_exponent == null ? 2 : Number(ctx.currency_exponent);
  const stored = Number(ctx.rent_minor) / Math.pow(10, exp);
  const storedMonthly = monthlyOf(stored, ctx.rent_period);
  const cur = normCurrency(ctx.currency);
  for (const p of pricesInText) {
    if (!p || typeof p.amount !== 'number' || p.amount <= 0) continue;
    const pc = normCurrency(p.currency);
    if (pc && cur && pc !== cur) continue;
    const c = normText(p.context);
    if (!RENT_CTX.test(c)) continue;
    if (OTHER_CTX.test(c) && !RENT_WORD.test(c)) continue;
    if (!amountInText(p.amount, ctx.text)) { dropped.push({ type: 'price_mismatch', reason: 'amount_not_in_text' }); continue; }
    const r = (x) => Math.max(p.amount, x) / Math.min(p.amount, x);
    const best = Math.min(r(stored), r(storedMonthly));
    if (best >= 1.5) {
      return { type: 'price_mismatch', source: 'rule', weight: W.price_mismatch || 0,
        evidence: { stored_main: stored, text_amount: p.amount, ratio: Math.round(best * 100) / 100, context: c.slice(0, 40) } };
    }
  }
  return null;
}

function profileSignals(ctx, S, W) {
  const o = ctx.owner || {};
  const out = [];
  const days = S['scam.new_account_days'];
  const burst = S['scam.burst_listings_24h'];
  if (o.account_age_days != null && days != null && o.account_age_days < days) {
    out.push({ type: 'new_account', source: 'rule', weight: W.new_account || 0, evidence: { account_age_days: o.account_age_days } });
  }
  if (o.account_age_days != null && o.verified_level === 0) {
    out.push({ type: 'unverified_owner', source: 'rule', weight: W.unverified_owner || 0, evidence: { verified_level: 0 } });
  }
  if (burst != null && o.listings_24h != null && o.listings_24h >= burst) {
    out.push({ type: 'listing_burst', source: 'rule', weight: W.listing_burst || 0, evidence: { listings_24h: o.listings_24h } });
  }
  return out;
}

// Results of the agent's contact_reuse tool (database counts). Kept only for a contact that is really written in the
// listing, so the agent cannot raise the score with a contact it made up; the largest reuse wins.
function contactSignal(reuse, text, W, dropped) {
  let best = null;
  for (const x of Array.isArray(reuse) ? reuse : []) {
    if (!x || !(Number(x.other_owners) > 0)) continue;
    if (!contactInText(x.contact, text)) { dropped.push({ type: 'contact_reused', reason: 'contact_not_in_text' }); continue; }
    if (!best || Number(x.other_listings) > best.other_listings) {
      best = { other_listings: Number(x.other_listings) || 0, other_owners: Number(x.other_owners) || 0 };
    }
  }
  if (!best) return null;
  return { type: 'contact_reused', source: 'rule', weight: W.contact_reused ?? CONTACT_REUSED_WEIGHT, evidence: best };
}

// Signals of the model kept only if the type is allowed and the quote is really in the text (one per type).
function modelSignals(output, text, W) {
  const kept = [], dropped = [];
  const seen = new Set();
  const list = output && Array.isArray(output.signals) ? output.signals : [];
  for (const s of list) {
    if (!s || !MODEL_TYPES.includes(s.type)) { dropped.push({ type: (s && s.type) || null, reason: 'unknown_type' }); continue; }
    if (!quoteInText(s.quote, text)) { dropped.push({ type: s.type, reason: 'quote_not_in_text' }); continue; }
    if (seen.has(s.type)) continue;
    seen.add(s.type);
    kept.push({ type: s.type, source: 'model', weight: W[s.type] || 0, evidence: { quote: String(s.quote).slice(0, 160) } });
  }
  return { kept, dropped };
}

// ctx: app.scam_context; modelOutput: the agent's answer or null (model unavailable);
// extra.contact_reuse: results of the contact_reuse tool. Returns {score, level, signals, dropped}.
function scamScore(ctx, modelOutput, extra = {}) {
  const S = ctx.settings || {};
  requireSettings(S);
  const W = S['scam.weights'];
  const T = S['scam.thresholds'];
  const signals = [], ruleDropped = [];
  const p = priceSignal(ctx, W); if (p) signals.push(p);
  const mm = mismatchSignal(ctx, modelOutput && modelOutput.prices_in_text, W, ruleDropped); if (mm) signals.push(mm);
  signals.push(...profileSignals(ctx, S, W));
  const cr = contactSignal(extra && extra.contact_reuse, ctx.text, W, ruleDropped); if (cr) signals.push(cr);
  const ms = modelSignals(modelOutput, ctx.text, W);
  signals.push(...ms.kept);
  const score = Math.min(100, signals.reduce((a, s) => a + (s.weight || 0), 0));
  const level = score >= T.block ? 'high' : score >= T.review ? 'medium' : 'low';
  return { score, level, signals, dropped: [...ms.dropped, ...ruleDropped] };
}

if (typeof module !== 'undefined') module.exports = { scamScore, quoteInText, normCurrency, amountInText, contactInText };

const r = $input.first().json;
const g = $('Agent output').first().json;
const c = $('Context').first().json.ctx;
if (!c || c.ok === false) {
  return [{ json: { ok: false, store: false, listing_id: (c && c.listing_id) || null, transient: false,
    error: `context: ${(c && c.error_code) || 'no answer'}`, steps: [] } }];
}
const out = r.ok ? r.output : null;
const res = scamScore(c, out, { contact_reuse: g.contact_reuse });
const steps = [
  { agent: 'A4_scam_agent', prompt_version_id: g.agent_prompt_version_id, model: g.agent_model,
    input: { chars: Array.from(String(c.text || '')).length, jurisdiction: c.jurisdiction_code },
    output: { note: !!g.note, contact_reuse: (g.contact_reuse || []).length }, tool_calls: (g.tool_calls || []).map((t) => ({ tool: t })),
    latency_ms: g.agent_latency_ms || 0, tokens_in: 0, tokens_out: 0, error: g.agent_ok ? null : g.agent_error },
  { agent: 'A4_scam_detector', prompt_version_id: r.prompt_version_id || null, model: r.model || null,
    input: { chars: Array.from(String(c.text || '')).length },
    output: r.ok ? { signals: res.signals.length, dropped: res.dropped.length, score: res.score } : { error_code: r.error_code },
    latency_ms: r.latency_ms || 0, tokens_in: r.tokens_in || 0, tokens_out: r.tokens_out || 0,
    error: r.ok ? null : `${r.error_code}${r.detail ? ': ' + String(r.detail).slice(0, 200) : ''}` }];
const detail = { prompt_version_id: r.prompt_version_id || null, model: r.model || null, model_ok: !!r.ok,
  agent: { ok: !!g.agent_ok, prompt_version_id: g.agent_prompt_version_id, tool_calls: g.tool_calls || [], error: g.agent_error || null },
  note: g.note || null, contact_reuse: g.contact_reuse || [],
  dropped: res.dropped, prices_in_text: out ? out.prices_in_text : null, market: c.market };
return [{ json: { ok: true, store: true, listing_id: c.listing_id, steps,
  params: [c.listing_id, JSON.stringify({ score: res.score, level: res.level, signals: res.signals, detail })],
  summary: { score: res.score, level: res.level, signals: res.signals.map((s) => s.type), model_ok: !!r.ok,
    agent_ok: !!g.agent_ok, tool_calls: g.tool_calls || [], note: g.note || null } } }];

// wf.scam.check > "Result": {ok, status, listing_id, check_id, score, level, signals, model_ok, transient, error, steps}.
// status: checked, not_found (no such listing), failed (storage). A model failure is not a failure: rules still score.
const c = $('Context').first().json.ctx;
if (!c || c.ok !== true) {
  return [{ json: { ok: false, status: 'not_found', listing_id: $('Start').first().json.listing_id || null,
    transient: false, error: `context: ${(c && c.error_code) || 'no answer'}`, steps: [] } }];
}
const x = $('Score').first().json;
if (!x.ok) return [{ json: { ok: false, status: 'failed', listing_id: x.listing_id, transient: x.transient, error: x.error, steps: x.steps } }];
const st = ($('Store check').first().json || {}).r || {};
if (!st.ok) {
  return [{ json: { ok: false, status: 'failed', listing_id: x.listing_id, transient: false,
    error: `store: ${st.error_code || 'no answer'}${st.field ? ' (' + st.field + ')' : ''}`, steps: x.steps } }];
}
return [{ json: { ok: true, status: 'checked', listing_id: x.listing_id, check_id: st.check_id, ...x.summary,
  transient: false, error: null, steps: x.steps } }];
